#[cfg(test)]
mod tests {
    use super::*;
    use std::thread;
    #[test]
    fn test_concurrent_increment() {
        let counter = ThreadSafeCounter::new();
        let mut handles = vec![];
        for _ in 0..10 {
            let c = counter.clone();
            handles.push(thread::spawn(move || {
                for _ in 0..100 {
                    c.increment();
                }
            }));
        }
        for h in handles {
            h.join().unwrap();
        }
        assert_eq!(counter.get(), 1000);
    }
}

