const { retryOperation } = require('./retry');
(async () => {
  let attempts = 0;
  const res = await retryOperation(async () => {
    attempts++;
    if (attempts < 3) throw new Error('transient');
    return 42;
  }, 5, 5);
  if (res !== 42 || attempts !== 3) process.exit(1);
